toolScript:
let currentFreq = 60;
        let isTesting = false;
        let flickerOn = false;
        let flickerInterval = null;
        let trials = [];
        let currentDirection = 'down';
        let correctCount = 0;
        let trialCount = 0;
        const TARGET_TRIALS = 6;

        function startTest() {
            isTesting = true;
            trials = [];
            correctCount = 0;
            trialCount = 0;
            currentFreq = 60;
            currentDirection = 'down';
            document.getElementById('test-controls').classList.add('hidden');
            document.getElementById('response-controls').classList.remove('hidden');
            document.getElementById('results-summary').classList.add('hidden');
            document.getElementById('trial-dots').innerHTML = '';
            document.getElementById('instruction').textContent = 'Focus on the center. Respond when ready.';
            updateFrequencyDisplay();
            nextTrial();
        }

        function nextTrial() {
            if (trialCount >= TARGET_TRIALS) {
                endTest();
                return;
            }
            const dot = document.createElement('div');
            dot.className = 'w-3 h-3 rounded-full bg-slate-400';
            dot.id = 'trial-dot-' + trialCount;
            document.getElementById('trial-dots').appendChild(dot);

            currentDirection = Math.random() > 0.5 ? 'down' : 'up';
            currentFreq = currentDirection === 'down' ? 65 : 55;
            updateFrequencyDisplay();
            startFlicker();

            setTimeout(() => {
                stopFlicker();
                document.getElementById('instruction').textContent = 'Do you see flicker or is it steady?';
            }, 2000);
        }

        function startFlicker() {
            const target = document.getElementById('flicker-target');
            target.classList.add('flickering', 'testing-indicator');
            flickerOn = true;
            flickerInterval = setInterval(() => {
                flickerOn = !flickerOn;
                target.style.background = flickerOn ? '#f97316' : '#1e1e1e';
            }, 1000 / (currentFreq / 2));
        }

        function stopFlicker() {
            if (flickerInterval) {
                clearInterval(flickerInterval);
                flickerInterval = null;
            }
            const target = document.getElementById('flicker-target');
            target.classList.remove('flickering', 'testing-indicator');
            target.classList.add('continuous');
        }

        function updateFrequencyDisplay() {
            document.getElementById('freq-display').textContent = Math.round(currentFreq);
        }

        function respond(response) {
            const isActuallyFlickering = currentFreq < 60;
            const dot = document.getElementById('trial-dot-' + trialCount);

            let correct = false;
            if (isActuallyFlickering && response === 'flicker') {
                correct = true;
            } else if (!isActuallyFlickering && response === 'fuse') {
                correct = true;
            }

            if (correct) {
                correctCount++;
                dot.classList.remove('bg-slate-400');
                dot.classList.add('bg-green-500');
            } else {
                dot.classList.remove('bg-slate-400');
                dot.classList.add('bg-red-500');
            }

            trials.push({ freq: currentFreq, response, correct });
            trialCount++;
            document.getElementById('trials-completed').textContent = trialCount;

            const step = currentDirection === 'down' ? -2 : 2;
            currentFreq += step;
            currentFreq = Math.max(30, Math.min(80, currentFreq));
            updateFrequencyDisplay();

            setTimeout(() => {
                document.getElementById('flicker-target').classList.remove('continuous');
                nextTrial();
            }, 500);
        }

        function endTest() {
            isTesting = false;
            document.getElementById('test-controls').classList.remove('hidden');
            document.getElementById('response-controls').classList.add('hidden');
            document.getElementById('results-summary').classList.remove('hidden');
            document.getElementById('instruction').textContent = 'Test complete!';

            const avgFreq = trials.reduce((sum, t) => sum + t.freq, 0) / trials.length;
            const estimatedAge = Math.round(90 - avgFreq);
            const accuracy = Math.round((correctCount / TARGET_TRIALS) * 100);

            document.getElementById('avg-cff').textContent = Math.round(avgFreq);
            document.getElementById('age-estimate').textContent = estimatedAge + ' yrs';
            document.getElementById('accuracy').textContent = accuracy + '%';
        }
